// L2.THE_CONTRACT_ONLY_BREAKS_ON_PURPOSE: a change to packages/services/openapi.json
// that oasdiff reports as breaking at ERR is refused unless the same change
// raises the contract's major (docs/design/amy-speaks-in-domains.md).
//
// The base is the document at the merge-base with the default branch, or the
// file `--base` names, which is how a mutation fixture brings its own.
import { execFileSync, spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { report, root, services } from "./read.js";

const DOCUMENT = "packages/services/openapi.json";
const findings: string[] = [];
const head = path.join(services, "openapi.json");
const base = baseDocument();

if (base !== undefined && fs.existsSync(head)) {
  const raised = majorOf(fs.readFileSync(head, "utf8")) > majorOf(base);
  if (!raised) {
    const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "amy-contract-"));
    const before = path.join(scratch, "base.json");
    fs.writeFileSync(before, base);
    const run = spawnSync("oasdiff", ["breaking", before, head, "--fail-on", "ERR", "--format", "singleline"], { encoding: "utf8" });
    if (run.error) {
      findings.push(`oasdiff did not run (${run.error.message}): it is pinned in .software-factory/toolchain.lock.json and ./scripts/setup-dev.sh installs it`);
    } else if (run.status !== 0) {
      const said = `${run.stdout}${run.stderr}`.trim().split("\n").filter(Boolean);
      findings.push(`${DOCUMENT} breaks its contract without raising API_MAJOR in packages/services/src/contract.ts:`, ...said.map((one) => `  ${one}`));
    }
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}

function baseDocument(): string | undefined {
  const named = process.argv.indexOf("--base");
  if (named !== -1) {
    const file = path.resolve(root, process.argv[named + 1] ?? "");
    return fs.existsSync(file) ? fs.readFileSync(file, "utf8") : undefined;
  }
  const ref = ["origin/main", "main"].find((candidate) => git(["rev-parse", "--verify", "--quiet", candidate]) !== undefined);
  const mergeBase = ref === undefined ? undefined : git(["merge-base", "HEAD", ref])?.trim();
  return mergeBase === undefined ? undefined : git(["show", `${mergeBase}:${DOCUMENT}`]);
}

function git(args: string[]): string | undefined {
  try {
    return execFileSync("git", args, { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
  } catch {
    return undefined;
  }
}

function majorOf(text: string): number {
  const version = (JSON.parse(text) as { info?: { version?: string } }).info?.version ?? "0";
  return Number(version.split(".")[0]) || 0;
}

report("L2.THE_CONTRACT_ONLY_BREAKS_ON_PURPOSE", findings);

// L4.THE_CONTRACT_DOCUMENTS_ITSELF: every operation in packages/services/openapi.json
// says what it is, every property says what it holds, every input and output
// has an example, every error is the envelope and every code is
// `<domain>.<reason>` (docs/design/amy-speaks-in-domains.md).
import fs from "node:fs";
import path from "node:path";
import { report, services } from "./read.js";

type Json = Record<string, unknown>;
const CODE = /^[a-z][a-z0-9-]*\.[a-z][a-z0-9_]*$/;
const findings: string[] = [];
const file = path.join(services, "openapi.json");

if (!fs.existsSync(file)) {
  findings.push("packages/services/openapi.json does not exist: `npm run build` writes it from the contract");
} else {
  const document = JSON.parse(fs.readFileSync(file, "utf8")) as Json;
  if (document.openapi !== "3.1.0") findings.push(`packages/services/openapi.json is OpenAPI ${String(document.openapi)}, not 3.1.0`);
  checkEnvelope(document);
  for (const [route, methods] of Object.entries((document.paths ?? {}) as Record<string, Record<string, Json>>)) {
    for (const [method, operation] of Object.entries(methods)) checkOperation(`${method.toUpperCase()} ${route}`, operation);
  }
}

function checkEnvelope(document: Json): void {
  const error = ((document.components as Json | undefined)?.schemas as Json | undefined)?.Error as Json | undefined;
  const required = (error?.required ?? []) as string[];
  if (!error || !required.includes("code") || !required.includes("message")) {
    findings.push("components.schemas.Error is not the envelope { code, message, details? }");
  }
}

function checkOperation(where: string, operation: Json): void {
  const id = typeof operation.operationId === "string" && operation.operationId ? operation.operationId : undefined;
  const name = id ?? where;
  if (!id) findings.push(`${where} has no operationId`);
  for (const field of ["summary", "description", "x-amy-domain"]) {
    if (typeof operation[field] !== "string" || operation[field] === "") findings.push(`\`${name}\` has no ${field}`);
  }
  if (typeof operation["x-amy-local-only"] !== "boolean") findings.push(`\`${name}\` has no x-amy-local-only`);
  if (!Array.isArray(operation["x-amy-writes"])) findings.push(`\`${name}\` has no x-amy-writes`);
  checkExamples(name, operation["x-amy-examples"]);
  for (const [at, schema] of schemasOf(operation)) checkDescribed(name, at, schema);
  checkErrors(name, operation);
}

function checkExamples(name: string, examples: unknown): void {
  const first = Array.isArray(examples) ? (examples[0] as Json | undefined) : undefined;
  if (!first || !("input" in first) || !("output" in first)) findings.push(`\`${name}\` has no example of its input and its output`);
}

function schemasOf(operation: Json): [string, Json][] {
  return [...inputSchemas(operation), ...outputSchemas(operation)];
}

function inputSchemas(operation: Json): [string, Json][] {
  const found: [string, Json][] = [];
  const body = ((operation.requestBody as Json | undefined)?.content as Record<string, Json> | undefined)?.["application/json"]?.schema as Json | undefined;
  if (body) found.push(["input", body]);
  for (const parameter of (operation.parameters ?? []) as Json[]) {
    if (typeof parameter.description !== "string" || parameter.description === "") findings.push(`\`${String(operation.operationId)}\` input property \`${String(parameter.name)}\` has no description`);
    if (parameter.schema) found.push([`input.${String(parameter.name)}`, parameter.schema as Json]);
  }
  return found;
}

function outputSchemas(operation: Json): [string, Json][] {
  const answers = Object.entries((operation.responses ?? {}) as Record<string, Json>).filter(([status]) => status !== "default");
  return answers.flatMap(([, response]) =>
    Object.values((response.content ?? {}) as Record<string, Json>).flatMap((media): [string, Json][] => {
      const events = media["x-amy-events"] as Record<string, Json> | undefined;
      if (events) return Object.entries(events).map(([event, schema]): [string, Json] => [`event ${event}`, schema]);
      return media.schema ? [["output", media.schema as Json]] : [];
    }),
  );
}

/** Every property, at any depth, carries a description. */
function checkDescribed(name: string, at: string, schema: Json): void {
  for (const [property, inner] of Object.entries((schema.properties ?? {}) as Record<string, Json>)) {
    if (typeof inner.description !== "string" || inner.description === "") findings.push(`\`${name}\` ${at} property \`${property}\` has no description`);
    checkDescribed(name, `${at}.${property}`, inner);
  }
  for (const [where, inner] of nested(at, schema)) checkDescribed(name, where, inner);
}

/** The schemas inside one that are not its properties: items, tuple elements, branches, and the $defs a $ref points at. */
function nested(at: string, schema: Json): [string, Json][] {
  const found: [string, Json][] = [];
  for (const key of ["items", "additionalProperties"]) {
    if (schema[key] && typeof schema[key] === "object") found.push([`${at}[]`, schema[key] as Json]);
  }
  for (const key of ["prefixItems", "anyOf", "oneOf", "allOf"]) found.push(...((schema[key] ?? []) as Json[]).map((branch): [string, Json] => [at, branch]));
  for (const [definition, inner] of Object.entries((schema.$defs ?? {}) as Record<string, Json>)) found.push([`${at}.$defs.${definition}`, inner]);
  return found;
}

function checkErrors(name: string, operation: Json): void {
  const failure = (((operation.responses as Json | undefined)?.default as Json | undefined)?.content as Record<string, Json> | undefined)?.["application/json"]?.schema as Json | undefined;
  const envelope = ((failure?.allOf ?? []) as Json[]).some((one) => one.$ref === "#/components/schemas/Error");
  if (!envelope) findings.push(`\`${name}\` answers its errors with something other than the envelope`);
  const domain = String(operation["x-amy-domain"]);
  for (const code of Object.keys((failure?.["x-amy-errors"] ?? {}) as Json)) {
    if (!CODE.test(code) || !code.startsWith(`${domain}.`)) findings.push(`\`${name}\` declares the error \`${code}\`, which is not \`${domain}.<reason>\``);
  }
}

report("L4.THE_CONTRACT_DOCUMENTS_ITSELF", findings);

// L3.EVERY_DECLARED_ERROR_IS_TESTED: every (operation, error code) the document
// declares is an outcome some test of the services produced through invoke.
// A declared error nobody has seen is a promise nobody checked
// (docs/design/amy-speaks-in-domains.md).
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { report, repository, root, services } from "./read.js";

type Json = Record<string, unknown>;
const findings: string[] = [];
const declared = declaredErrors();

if (declared.length > 0) {
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "amy-outcomes-"));
  const record = path.join(scratch, "outcomes.jsonl");
  fs.writeFileSync(record, "");
  const vitest = path.join(repository, "node_modules/.bin/vitest");
  const run = spawnSync(vitest, ["run", "--config", path.join(repository, "packages/services/gates/outcomes.config.ts")], {
    cwd: root,
    encoding: "utf8",
    env: { ...process.env, AMY_OUTCOMES: record },
  });
  if (run.status !== 0) findings.push(`the services' tests failed, so no outcome they record can be trusted:\n${run.stdout}${run.stderr}`);
  const seen = new Set(
    fs
      .readFileSync(record, "utf8")
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line) as { operation: string; kind: string; code?: string })
      .filter((one) => one.kind === "error")
      .map((one) => `${one.operation} ${one.code}`),
  );
  for (const [operation, code] of declared) {
    if (!seen.has(`${operation} ${code}`)) findings.push(`\`${operation}\` declares \`${code}\`, and no test produced it through invoke`);
  }
  fs.rmSync(scratch, { recursive: true, force: true });
}

function declaredErrors(): [string, string][] {
  const file = path.join(services, "openapi.json");
  if (!fs.existsSync(file)) return [];
  const document = JSON.parse(fs.readFileSync(file, "utf8")) as { paths?: Record<string, Record<string, Json>> };
  const found: [string, string][] = [];
  for (const methods of Object.values(document.paths ?? {})) {
    for (const operation of Object.values(methods)) {
      const failure = (((operation.responses as Json | undefined)?.default as Json | undefined)?.content as Record<string, Json> | undefined)?.["application/json"]?.schema as Json | undefined;
      for (const code of Object.keys((failure?.["x-amy-errors"] ?? {}) as Json)) found.push([String(operation.operationId), code]);
    }
  }
  return found;
}

report("L3.EVERY_DECLARED_ERROR_IS_TESTED", findings);

// L0.THE_SERVICES_KEEP_NO_DATABASE: the ports are the truth. No driver or ORM
// under packages/services, no filesystem outside a repository, no file
// adapter named in a domain, and a repository awaits every port call so a
// port answering over a network changes no domain
// (docs/design/amy-speaks-in-domains.md).
import path from "node:path";
import ts from "typescript";
import { domainOf, importsOf, partOf, portBindings, portNamedBy, portNames, report, services, sourcesUnder, type Source } from "./read.js";

const DRIVERS = /^(better-sqlite3|sqlite3|pg|mysql2|prisma|@prisma\/client|drizzle-orm|typeorm|knex|level|lmdb)(\/|$)/;
const FILESYSTEM = /^(node:)?fs(\/promises)?$/;
const FILE_ADAPTERS = new Set(["FileStore", "FileQueue", "FileEventLog", "FileStopSwitch", "PAUSED"]);
const findings: string[] = [];
const ports = portNames();

for (const source of sourcesUnder(services)) {
  for (const one of importsOf(source)) {
    if (DRIVERS.test(one.specifier)) findings.push(`${source.file} imports \`${one.specifier}\`: amy ships no database; state kept elsewhere is an adapter behind a port`);
  }
}

for (const source of sourcesUnder(path.join(services, "src"))) {
  const inDomain = domainOf(source.absolute) !== undefined;
  const part = partOf(source.absolute);
  for (const one of importsOf(source)) {
    if (FILESYSTEM.test(one.specifier) && part !== "repositories") {
      findings.push(`${source.file} imports \`${one.specifier}\`: only a repository touches what a port persists, and it does so through the port`);
    }
    if (inDomain && (one.specifier.startsWith("@amykit/plugin-file-") || one.names.some((name) => FILE_ADAPTERS.has(name)))) {
      findings.push(`${source.file} names a file adapter (\`${one.specifier}\`): a domain is handed the port's interface, never the adapter behind it`);
    }
  }
  if (part === "repositories") checkAwaits(source);
}

/** Every call on a field or parameter typed as a port is awaited. */
function checkAwaits(source: Source): void {
  const held = portHolders(source);
  const visit = (node: ts.Node): void => {
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
      const holder = holderName(node.expression.expression);
      if (holder !== undefined && held.has(holder) && !isAwaited(node)) {
        findings.push(`${source.file}:${line(source.ast, node)} calls \`${node.expression.getText(source.ast)}\` without awaiting it: a repository awaits every port call, synchronous or not`);
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(source.ast);
}

/** The names of parameters, properties and variables whose declared type is a port, however the port was imported. */
function portHolders(source: Source): Set<string> {
  const bindings = portBindings(source, ports);
  const names = new Set<string>();
  const visit = (node: ts.Node): void => {
    if ((ts.isParameter(node) || ts.isPropertyDeclaration(node) || ts.isVariableDeclaration(node)) && node.type && ts.isIdentifier(node.name)) {
      if (ts.isTypeReferenceNode(node.type) && portNamedBy(node.type.typeName, bindings, ports) !== undefined) names.add(node.name.text);
    }
    ts.forEachChild(node, visit);
  };
  visit(source.ast);
  return names;
}

function holderName(node: ts.Expression): string | undefined {
  if (ts.isIdentifier(node)) return node.text;
  if (ts.isPropertyAccessExpression(node) && node.expression.kind === ts.SyntaxKind.ThisKeyword) return node.name.text;
  return undefined;
}

function isAwaited(node: ts.Node): boolean {
  let parent = node.parent;
  while (ts.isParenthesizedExpression(parent)) parent = parent.parent;
  return ts.isAwaitExpression(parent);
}

function line(file: ts.SourceFile, node: ts.Node): number {
  return file.getLineAndCharacterOfPosition(node.getStart(file)).line + 1;
}

report("L0.THE_SERVICES_KEEP_NO_DATABASE", findings);

// L0.THE_SERVICES_KEEP_THEIR_DOMAINS: each domain keeps its layout, an
// operation file exports its operation and nothing else, no domain reads
// another, only a repository names a port, and no transport is imported
// anywhere under packages/services (docs/design/amy-speaks-in-domains.md).
import fs from "node:fs";
import path from "node:path";
import ts from "typescript";
import { domainOf, domains, importsOf, landsAt, partOf, portBindings, portNamedBy, portNames, report, services, sourcesUnder, type Source } from "./read.js";

const REQUIRED = ["operations", "services", "exceptions.ts", "index.ts"];
const TRANSPORTS = /^(commander|hono|express|fastify|koa|ws|node:(http|https|http2|net)|http|https|http2|net)(\/|$)/;
const findings: string[] = [];
const ports = portNames();

for (const domain of domains()) {
  for (const part of REQUIRED) {
    if (!fs.existsSync(path.join(domain.directory, part))) findings.push(`domain \`${domain.name}\` has no ${part}: every domain keeps operations/, services/, exceptions.ts and index.ts`);
  }
}

for (const source of sourcesUnder(services)) {
  for (const one of importsOf(source)) {
    if (TRANSPORTS.test(one.specifier)) findings.push(`${source.file} imports \`${one.specifier}\`: a transport belongs to its door, never to the services`);
  }
  const domain = domainOf(source.absolute);
  if (domain === undefined) continue;
  const part = partOf(source.absolute);
  checkImports(source, domain, part);
  if (part === "operations") checkOperationExports(source);
}

function checkImports(source: Source, domain: string, part: string | undefined): void {
  for (const one of importsOf(source)) {
    const target = landsAt(source, one.specifier);
    if (target !== undefined) checkReach(source, one.specifier, target, domain, part);
  }
  if (part === "operations" || part === "services") checkPorts(source);
}

/** A relative import stays in its own domain, and a service never reaches an operation. */
function checkReach(source: Source, specifier: string, target: string, domain: string, part: string | undefined): void {
  const reached = domainOf(target);
  if (reached !== undefined && reached !== domain) {
    findings.push(`${source.file} imports \`${specifier}\` from domain \`${reached}\`: domain \`${domain}\` reads no other domain, it reads the record through its own repository`);
  }
  if (part === "services" && reached === domain && partOf(target) === "operations") {
    findings.push(`${source.file} imports the operation \`${specifier}\`: a service is called by an operation, never the other way`);
  }
}

/** A port named outside a repository: by name, by alias, through a namespace, or behind an `import()`. */
function checkPorts(source: Source): void {
  const bindings = portBindings(source, ports);
  for (const port of new Set(bindings.named.values())) findings.push(`${source.file} imports the port \`${port}\`: only a repository reaches a port`);
  for (const line of bindings.dynamic) findings.push(`${source.file}:${line} loads @amykit/core dynamically: import what you use by name, and a port only from a repository`);
  const seen = new Set<string>();
  const visit = (node: ts.Node): void => {
    const port = ts.isQualifiedName(node) || ts.isPropertyAccessExpression(node) ? portNamedBy(node, bindings, ports) : undefined;
    if (port !== undefined && !seen.has(port)) {
      seen.add(port);
      findings.push(`${source.file} reaches the port \`${port}\` through a namespace: only a repository reaches a port`);
    }
    ts.forEachChild(node, visit);
  };
  visit(source.ast);
}

function checkOperationExports(source: Source): void {
  const exported = exportsOf(source.ast);
  const operations = exported.filter((one) => one.isOperation);
  for (const one of exported.filter((candidate) => !candidate.isOperation)) {
    findings.push(`${source.file} exports \`${one.name}\`: an operation file exports its operation and nothing else, its schemas and types included`);
  }
  if (operations.length !== 1) findings.push(`${source.file} exports ${operations.length} operations: an operation file declares exactly one`);
}

function exportsOf(file: ts.SourceFile): { name: string; isOperation: boolean }[] {
  const found: { name: string; isOperation: boolean }[] = [];
  for (const statement of file.statements) {
    const exported = ts.canHaveModifiers(statement) && ts.getModifiers(statement)?.some((one) => one.kind === ts.SyntaxKind.ExportKeyword);
    if (ts.isVariableStatement(statement) && exported) {
      for (const declaration of statement.declarationList.declarations) {
        found.push({ name: declaration.name.getText(file), isOperation: isDefineOperation(declaration.initializer) });
      }
    } else if (ts.isExportDeclaration(statement) || ts.isExportAssignment(statement)) {
      found.push({ name: statement.getText(file), isOperation: false });
    } else if (exported && "name" in statement && statement.name) {
      found.push({ name: (statement.name as ts.Identifier).text, isOperation: false });
    }
  }
  return found;
}

function isDefineOperation(node: ts.Expression | undefined): boolean {
  return node !== undefined && ts.isCallExpression(node) && ts.isIdentifier(node.expression) && node.expression.text === "defineOperation";
}

report("L0.THE_SERVICES_KEEP_THEIR_DOMAINS", findings);

// The services' tests, run from the root of the tree a gate judges, with the
// core resolved from the repository the gate lives in.
import path from "node:path";
import { defineConfig } from "vitest/config";

const root = process.cwd();
const repository = path.resolve(import.meta.dirname, "../../..");

export default defineConfig({
  root,
  test: {
    include: ["packages/services/tests/**/*.test.ts"],
    // The gates' own test drives these gates; run here it would recurse.
    exclude: ["**/node_modules/**", "packages/services/tests/gates.test.ts"],
  },
  resolve: {
    alias: {
      "@amykit/core": path.join(repository, "packages/core/src/index.ts"),
      "@amykit/plugin-file-store": path.join(repository, "plugins/file-store/src/index.ts"),
      "@amykit/services": path.join(root, "packages/services/src/index.ts"),
    },
  },
});

// What the services' gates read: every source file under a tree's
// packages/services, as the TypeScript compiler parses it. Each gate runs from
// the root of the tree it judges — the repository, or a mutation fixture —
// and reads the core's ports from the repository it lives in.
import fs from "node:fs";
import path from "node:path";
import ts from "typescript";

export const root = process.cwd();
export const services = path.join(root, "packages/services");
export const domainsDir = path.join(services, "src/domains");
/** The repository this gate lives in, wherever the tree it judges sits. */
export const repository = path.resolve(import.meta.dirname, "../../..");

export interface Source {
  /** Relative to the tree's root, with forward slashes. */
  readonly file: string;
  readonly absolute: string;
  readonly ast: ts.SourceFile;
}

export interface Import {
  readonly specifier: string;
  /** The names it binds, `*` for a namespace, empty for a bare import. */
  readonly names: readonly string[];
}

/** Every extension the TypeScript build accepts as a source: .ts, .tsx, .mts and .cts. */
const SOURCE = /\.(ts|tsx|mts|cts)$/;
const DECLARATION = /\.d\.(ts|mts|cts)$/;

/** Every TypeScript source under a directory, skipping what a build or an install wrote. */
export function sourcesUnder(directory: string): Source[] {
  if (!fs.existsSync(directory)) return [];
  const found: Source[] = [];
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      if (entry.name !== "node_modules" && entry.name !== "dist") found.push(...sourcesUnder(absolute));
    } else if (SOURCE.test(entry.name) && !DECLARATION.test(entry.name)) {
      found.push(parse(absolute));
    }
  }
  return found.sort((a, b) => a.file.localeCompare(b.file));
}

export function parse(absolute: string): Source {
  const text = fs.readFileSync(absolute, "utf8");
  return {
    file: path.relative(root, absolute).split(path.sep).join("/"),
    absolute,
    ast: ts.createSourceFile(absolute, text, ts.ScriptTarget.Latest, true, absolute.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS),
  };
}

/** Every module a file reaches: static imports, re-exports, `import()` and `require()`. */
export function importsOf(source: Source): Import[] {
  const found: Import[] = [];
  const visit = (node: ts.Node): void => {
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
      found.push({ specifier: node.moduleSpecifier.text, names: boundNames(node.importClause) });
    } else if (ts.isExportDeclaration(node) && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      const names = node.exportClause && ts.isNamedExports(node.exportClause) ? node.exportClause.elements.map((one) => (one.propertyName ?? one.name).text) : ["*"];
      found.push({ specifier: node.moduleSpecifier.text, names });
    } else if (ts.isCallExpression(node) && isDynamicLoad(node) && node.arguments[0] && ts.isStringLiteralLike(node.arguments[0])) {
      found.push({ specifier: node.arguments[0].text, names: ["*"] });
    }
    ts.forEachChild(node, visit);
  };
  visit(source.ast);
  return found;
}

function boundNames(clause: ts.ImportClause | undefined): string[] {
  if (!clause) return [];
  const names: string[] = clause.name ? ["default"] : [];
  const bindings = clause.namedBindings;
  if (bindings && ts.isNamespaceImport(bindings)) names.push("*");
  if (bindings && ts.isNamedImports(bindings)) names.push(...bindings.elements.map((one) => (one.propertyName ?? one.name).text));
  return names;
}

function isDynamicLoad(node: ts.CallExpression): boolean {
  return node.expression.kind === ts.SyntaxKind.ImportKeyword || (ts.isIdentifier(node.expression) && node.expression.text === "require");
}

/** Where a relative import lands, as an absolute path without its extension. */
export function landsAt(source: Source, specifier: string): string | undefined {
  if (!specifier.startsWith(".")) return undefined;
  return path.resolve(path.dirname(source.absolute), specifier).replace(/\.(js|jsx|mjs|cjs|ts|tsx|mts|cts)$/, "");
}

/** One domain folder: its name and where it is. */
export interface Domain {
  readonly name: string;
  readonly directory: string;
}

export function domains(): Domain[] {
  if (!fs.existsSync(domainsDir)) return [];
  return fs
    .readdirSync(domainsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => ({ name: entry.name, directory: path.join(domainsDir, entry.name) }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

/** The domain a path sits in, if it sits in one. A file beside the domains, such as their index, is in none. */
export function domainOf(absolute: string): string | undefined {
  const relative = path.relative(domainsDir, absolute);
  if (relative.startsWith("..") || path.isAbsolute(relative)) return undefined;
  const segments = relative.split(path.sep);
  return segments.length > 1 || fs.statSync(absolute, { throwIfNoEntry: false })?.isDirectory() ? segments[0] : undefined;
}

/** The part of a domain a path sits in: `operations`, `services`, `repositories`, or a file at its root. */
export function partOf(absolute: string): string | undefined {
  const relative = path.relative(domainsDir, absolute);
  if (relative.startsWith("..")) return undefined;
  return relative.split(path.sep)[1];
}

/**
 * Every port the core declares: an exported interface or class under
 * packages/core/src/ports with something to call. Read from the repository
 * the gate lives in, so a fixture is judged against today's ports. A plain
 * value beside a port — a view, a result — is data, and any file may name it.
 */
export function portNames(): Set<string> {
  const names = new Set<string>();
  for (const source of sourcesUnder(path.join(repository, "packages/core/src/ports"))) {
    for (const statement of source.ast.statements) {
      const exported = ts.canHaveModifiers(statement) && ts.getModifiers(statement)?.some((one) => one.kind === ts.SyntaxKind.ExportKeyword);
      if (exported && (ts.isInterfaceDeclaration(statement) || ts.isClassDeclaration(statement)) && statement.name && hasSomethingToCall(statement)) {
        names.add(statement.name.text);
      }
    }
  }
  return names;
}

function hasSomethingToCall(declaration: ts.InterfaceDeclaration | ts.ClassDeclaration): boolean {
  return (declaration.members as ts.NodeArray<ts.Node>).some(
    (member) =>
      ts.isMethodSignature(member) ||
      ts.isMethodDeclaration(member) ||
      ((ts.isPropertySignature(member) || ts.isPropertyDeclaration(member)) && member.type !== undefined && ts.isFunctionTypeNode(member.type)),
  );
}

/** How a file binds the core's ports: local names for each port, and namespaces over the core. */
export interface PortBindings {
  /** Local name → the port it is, aliases included. */
  readonly named: ReadonlyMap<string, string>;
  /** Local names of `import * as x from "@amykit/core"`. */
  readonly namespaces: ReadonlySet<string>;
  /** Lines that load the core with `import()` or `require()`, whose exports nothing can see. */
  readonly dynamic: readonly number[];
}

export function portBindings(source: Source, ports: ReadonlySet<string>): PortBindings {
  const named = new Map<string, string>();
  const namespaces = new Set<string>();
  const dynamic: number[] = [];
  const visit = (node: ts.Node): void => {
    if (isCoreImport(node)) bindImport(node, ports, named, namespaces);
    else if (isCoreLoad(node)) dynamic.push(source.ast.getLineAndCharacterOfPosition(node.getStart(source.ast)).line + 1);
    ts.forEachChild(node, visit);
  };
  visit(source.ast);
  return { named, namespaces, dynamic };
}

function isCoreImport(node: ts.Node): node is ts.ImportDeclaration {
  return ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier) && node.moduleSpecifier.text === "@amykit/core";
}

function isCoreLoad(node: ts.Node): boolean {
  if (!ts.isCallExpression(node) || !isDynamicLoad(node)) return false;
  const first = node.arguments[0];
  return first !== undefined && ts.isStringLiteralLike(first) && first.text === "@amykit/core";
}

function bindImport(node: ts.ImportDeclaration, ports: ReadonlySet<string>, named: Map<string, string>, namespaces: Set<string>): void {
  const bindings = node.importClause?.namedBindings;
  if (bindings && ts.isNamespaceImport(bindings)) namespaces.add(bindings.name.text);
  if (!bindings || !ts.isNamedImports(bindings)) return;
  for (const one of bindings.elements) {
    const imported = (one.propertyName ?? one.name).text;
    if (ports.has(imported)) named.set(one.name.text, imported);
  }
}

/** The port a type or value reference names — `Store`, `NoteStore` aliased to it, or `core.Store` — if any. */
export function portNamedBy(node: ts.Node, bindings: PortBindings, ports: ReadonlySet<string>): string | undefined {
  if (ts.isIdentifier(node)) return bindings.named.get(node.text);
  const left = ts.isQualifiedName(node) ? node.left : ts.isPropertyAccessExpression(node) ? node.expression : undefined;
  const right = ts.isQualifiedName(node) ? node.right : ts.isPropertyAccessExpression(node) ? node.name : undefined;
  if (!left || !right || !ts.isIdentifier(left) || !ts.isIdentifier(right)) return undefined;
  return bindings.namespaces.has(left.text) && ports.has(right.text) ? right.text : undefined;
}

/** Prints the findings and sets the exit code: the shape every gate answers in. */
export function report(rule: string, findings: readonly string[]): void {
  if (findings.length === 0) {
    console.log(`${rule}: nothing to report`);
    return;
  }
  for (const finding of findings) console.error(finding);
  process.exitCode = 1;
}

